def train(args, rollout_manager):
    actor = create_training_models(args)
    actor.update_weights()          # first sync
    for rollout_id in range(start, args.num_rollout):
        data_ref = rollout_manager.generate(rollout_id)
        if args.offload_rollout:
            rollout_manager.offload()
        actor.async_train(rollout_id, data_ref)
        if should_save(rollout_id):
            save_checkpoint(args, rollout_id)
        offload_train()
        if args.offload_rollout:
            rollout_manager.onload_weights()
        actor.update_weights()      # Megatron to SGLang
        if args.offload_rollout:
            rollout_manager.onload_kv()

def create_weight_updater(args, ...):
    mode = args.update_weight_mode        # full | delta
    transport = args.update_weight_transport  # nccl | disk
    if mode == "delta":
        assert not args.colocate
        assert transport == "disk"
        cls = UpdateWeightFromDiskDelta
    elif transport == "disk":
        cls = UpdateWeightFromDisk
    elif args.colocate:
        cls = UpdateWeightFromTensor
    else:
        cls = UpdateWeightFromDistributed
    return cls(args, ...)
